"use client";

import { useState, useEffect, useCallback, useRef } from "react";

export interface StylePreset {
  id: string;
  name: string;
  /** Swatch preview colors (inline styles — duplicated from CSS tokens) */
  colors: { primary: string; accent: string; bg: string };
}

export interface UseStyleSwitcherOptions {
  storageKey: string;
  styles: StylePreset[];
  defaultStyle?: string;
}

export interface UseStyleSwitcherReturn {
  activeStyle: string;
  setStyle: (id: string) => void;
  mounted: boolean;
}

export function useStyleSwitcher({
  storageKey,
  styles,
  defaultStyle,
}: UseStyleSwitcherOptions): UseStyleSwitcherReturn {
  const fallback = defaultStyle ?? styles[0]?.id ?? "";
  const validIds = useRef(new Set(styles.map((s) => s.id)));
  const anchorRef = useRef<HTMLElement | null>(null);

  const [activeStyle, setActiveStyle] = useState(fallback);
  const [mounted, setMounted] = useState(false);

  // Read localStorage on mount, validate against known preset ids
  useEffect(() => {
    try {
      const stored = localStorage.getItem(storageKey);
      if (stored && validIds.current.has(stored)) {
        setActiveStyle(stored);
      }
    } catch {
      // localStorage unavailable — keep default
    }
    setMounted(true);
  }, [storageKey]);

  // Apply data-style attribute to closest [data-design] ancestor
  useEffect(() => {
    if (!mounted) return;

    // Find the design root — walk up from any element we can reference
    if (!anchorRef.current) {
      anchorRef.current = document.querySelector("[data-design]");
    }
    const designEl = anchorRef.current;
    if (!designEl) return;

    if (activeStyle === fallback) {
      designEl.removeAttribute("data-style");
    } else {
      designEl.setAttribute("data-style", activeStyle);
    }

    try {
      localStorage.setItem(storageKey, activeStyle);
    } catch {
      // localStorage unavailable — style still applies via DOM
    }
  }, [activeStyle, mounted, storageKey, fallback]);

  const setStyle = useCallback(
    (id: string) => {
      if (validIds.current.has(id)) {
        setActiveStyle(id);
      } else {
        setActiveStyle(fallback);
      }
    },
    [fallback],
  );

  return { activeStyle, setStyle, mounted };
}

