@import "tailwindcss";

/* Source directives — tell Tailwind to scan workspace packages for utility classes */
@source "../../../packages/ui/src";
@source "../../../packages/design-system/src";
@source "../../../packages/designs";
@source "../../../packages/shared/src";

/* Import keeper design themes — scoped by [data-design] attr, no conflicts */
@import "@imgen/design-04/theme.css";
@import "@imgen/design-08/theme.css";
@import "@imgen/design-12/theme.css";
@import "@imgen/design-13/theme.css";
@import "@imgen/design-15/theme.css";
@import "@imgen/design-28/theme.css";

/*
 * Fallback --design-* tokens for pages outside [data-design] scope.
 * Each design's theme.css overrides these within its [data-design="N"] selector.
 */
:root {
  --design-bg: #000;
  --design-fg: #fff;
  --design-card: #111;
  --design-card-fg: #eee;
  --design-primary: #3b82f6;
  --design-primary-fg: #fff;
  --design-secondary: #111;
  --design-secondary-fg: #ddd;
  --design-muted: #222;
  --design-muted-fg: #888;
  --design-accent: #3b82f6;
  --design-accent-fg: #fff;
  --design-destructive: #ef4444;
  --design-border: #222;
  --design-input: #111;
  --design-ring: #3b82f6;
  --design-radius-sm: 0.25rem;
  --design-radius-md: 0.375rem;
  --design-radius-lg: 0.5rem;
  --design-radius-xl: 0.75rem;
}

/*
 * Theme tokens — Tailwind utility classes (bg-background, text-primary, etc.)
 * resolve to var(--design-*) so each design's theme.css drives the actual values.
 */
@theme inline {
  --color-background: var(--design-bg);
  --color-foreground: var(--design-fg);
  --color-card: var(--design-card);
  --color-card-foreground: var(--design-card-fg);
  --color-primary: var(--design-primary);
  --color-primary-foreground: var(--design-primary-fg);
  --color-secondary: var(--design-secondary);
  --color-secondary-foreground: var(--design-secondary-fg);
  --color-muted: var(--design-muted);
  --color-muted-foreground: var(--design-muted-fg);
