import { notFound } from "next/navigation";
import { designFonts } from "@/lib/fonts";
import { getStyleStorageKey, getThemeStorageKey } from "@imgen/design-system/lib";

export default async function DesignLayout({
  children,
  params,
}: {
  children: React.ReactNode;
  params: Promise<{ designId: string }>;
}) {
  const { designId } = await params;
  const id = parseInt(designId, 10);
  if (isNaN(id) || id < 1 || id > 28) notFound();

  const fonts = designFonts[id];
  if (!fonts) notFound();

  const styleKey = getStyleStorageKey(id);
  const themeKey = getThemeStorageKey(id);

  return (
    <div data-design={id} className={fonts.classNames} suppressHydrationWarning>
      {/* Blocking script — restores style + theme before first paint to prevent FOUC */}
      <script
        dangerouslySetInnerHTML={{
          __html: `try{var el=document.currentScript.parentElement;var s=localStorage.getItem("${styleKey}");var t=localStorage.getItem("${themeKey}");if(s&&el)el.setAttribute("data-style",s);if(t&&el)el.setAttribute("data-theme",t)}catch(e){}`,
        }}
      />
      {children}
    </div>
  );
}

