file.content:
.ds-gen-bar-section {
  position: relative;
  padding: 2rem 1.5rem 5rem;
  display: flex;
  justify-content: center;
}

.ds-gen-bar-section.ds-gen-bar-section-floating {
  position: fixed;
  inset: auto 0 0;
  z-index: 50;
  padding: 0.75rem 1rem calc(0.75rem + env(safe-area-inset-bottom));
  background: linear-gradient(
    to top,
    color-mix(in oklch, var(--design-bg), transparent 8%) 0%,
    color-mix(in oklch, var(--design-bg), transparent 35%) 70%,
    transparent 100%
  );
  pointer-events: none;
}

.ds-gen-bar-section.ds-gen-bar-section-floating .ds-gen-bar-container {
  pointer-events: auto;
}

.ds-gen-bar-section.ds-gen-bar-section-floating .ds-gen-bar {
  box-shadow: 0 -8px 24px color-mix(in oklch, var(--design-fg), transparent 90%);
}

.ds-gen-bar-container {
  width: 100%;
  max-width: 44rem;
  position: relative;
}

.ds-gen-bar {
  position: relative;
  background: var(--design-card);
  border: 1px solid var(--design-border);
  border-radius: var(--design-radius-xl);
  overflow: hidden;
  transition:
    border-color 300ms ease,
    box-shadow 300ms ease;
}

.ds-gen-bar:focus-within {
  border-color: color-mix(in oklch, var(--design-primary), transparent 50%);
}

.ds-gen-bar.ds-gen-bar-idle {
  animation: ds-gen-breathe 3s ease-in-out infinite;
}

.ds-gen-bar.ds-gen-bar-generating {
  animation: none;
}

/* AC-2: Success state styling */
.ds-gen-bar.ds-gen-bar-success {
  animation: none;
  border-color: var(--design-primary);
}

/* AC-4: Drag overlay */
.ds-gen-bar-drag-overlay {
  position: absolute;
  inset: 0;
  background: color-mix(in oklch, var(--design-primary), transparent 90%);
  border: 2px dashed var(--design-primary);
  border-radius: var(--design-radius-xl);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1rem;
  color: var(--design-primary);
  z-index: 10;
  pointer-events: none;
}

/* Top row: image btn + textarea + overflow + create btn */
.ds-gen-bar-input-row {
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
  padding: 1rem 1rem 0.75rem;
}

.ds-gen-bar-image-btn {
  flex-shrink: 0;
  width: 2.25rem;
  height: 2.25rem;
  border-radius: var(--design-radius-md);
  border: 1.5px dashed var(--design-border);
  background: transparent;
  color: var(--design-muted-fg);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition:
    border-color 300ms ease,
    color 300ms ease;
  margin-top: 0.125rem;
}

.ds-gen-bar-image-btn:hover {
  border-color: var(--design-accent);
  color: var(--design-accent);
}

.ds-gen-bar-image-btn.ds-has-image {
  border-style: solid;
  border-color: var(--design-primary);
  color: var(--design-primary);
  background: color-mix(in oklch, var(--design-primary), transparent 90%);
}

/* Textarea wrapper for @-mention popup positioning */
.ds-gen-bar-textarea-wrapper {
  flex: 1;
  position: relative;
}

.ds-gen-bar-textarea {
  width: 100%;
  background: transparent;
  border: none;
  outline: none;
  resize: none;
  font-size: 1rem;
  line-height: 1.5;
  color: var(--design-fg);
  min-height: 2.25rem;
  max-height: 10rem;
  overflow-y: auto;
}

.ds-gen-bar-textarea::placeholder {
  color: var(--design-muted-fg);
  transition: opacity 400ms ease;
}

/* AC-1: Overflow menu button */
.ds-gen-bar-overflow {
  flex-shrink: 0;
  margin-top: 0.125rem;
}

.ds-gen-bar-overflow-btn {
  width: 2.25rem;
  height: 2.25rem;
  border-radius: var(--design-radius-md);
  border: 1px solid transparent;
  background: transparent;
  color: var(--design-muted-fg);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition:
    border-color 200ms ease,
    color 200ms ease,
    background 200ms ease;
}

.ds-gen-bar-overflow-btn:hover {
  border-color: var(--design-border);
  color: var(--design-fg);
  background: color-mix(in oklch, var(--design-accent), transparent 95%);
}

.ds-gen-bar-submit-btn {
  flex-shrink: 0;
  margin-top: 0.125rem;
  min-width: 5rem;
}

/* AC-2: Success state for submit button */
.ds-gen-bar-submit-btn.ds-success {
  background: var(--design-primary);
  color: var(--design-bg);
}

/* AC-6: Validation error message */
.ds-gen-bar-validation-error {
  padding: 0.5rem 1rem;
  font-size: 0.75rem;
  color: var(--design-destructive);
  background: color-mix(in oklch, var(--design-destructive), transparent 95%);
  border-top: 1px solid color-mix(in oklch, var(--design-destructive), transparent 80%);
}

/* AC-4: Image thumbnails area */
.ds-gen-bar-thumbnails {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  padding: 0.75rem 1rem;
  border-top: 1px solid var(--design-border);
}

.ds-gen-bar-thumbnail {
  position: relative;
  width: 4rem;
  height: 4rem;
  border-radius: var(--design-radius-md);
  overflow: hidden;
  border: 1px solid var(--design-border);
}

.ds-gen-bar-thumbnail img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.ds-gen-bar-thumbnail.ds-uploading {
  border-color: var(--design-accent);
}

.ds-gen-bar-thumbnail.ds-error {
  border-color: var(--design-destructive);
}

.ds-gen-bar-thumbnail-status {
  position: absolute;
  inset: auto 0 0 0;
  padding: 0.2rem 0.3rem;
  font-size: 0.625rem;
  line-height: 1.2;
  text-align: center;
  color: var(--design-fg);
  background: color-mix(in oklch, var(--design-bg), transparent 12%);
}

.ds-gen-bar-thumbnail.ds-error .ds-gen-bar-thumbnail-status {
  color: var(--design-destructive-fg);
  background: color-mix(in oklch, var(--design-destructive), transparent 12%);
}

.ds-gen-bar-thumbnail-remove {
  position: absolute;
  top: 0.125rem;
  right: 0.125rem;
  width: 1.25rem;
  height: 1.25rem;
  border-radius: 9999px;
  border: none;
  background: color-mix(in oklch, var(--design-bg), transparent 20%);
  color: var(--design-fg);
  cursor: pointer;
  font-size: 0.875rem;
  line-height: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  transition: opacity 200ms ease;
}

.ds-gen-bar-thumbnail:hover .ds-gen-bar-thumbnail-remove {
  opacity: 1;
}

/* AC-5: @-mention popup */
.ds-gen-bar-mention-popup {
  position: absolute;
  bottom: 100%;
  left: 0;
  right: 0;
  margin-bottom: 0.5rem;
  background: var(--design-card);
  border: 1px solid var(--design-border);
  border-radius: var(--design-radius-lg);
  box-shadow: 0 4px 12px color-mix(in oklch, var(--design-fg), transparent 90%);
  max-height: 16rem;
  overflow-y: auto;
  z-index: 20;
}

.ds-gen-bar-mention-item {
  width: 100%;
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.75rem 1rem;
  border: none;
  background: transparent;
  color: var(--design-fg);
  cursor: pointer;
  text-align: left;
  transition: background 200ms ease;
}

.ds-gen-bar-mention-item:hover {
  background: color-mix(in oklch, var(--design-accent), transparent 95%);
}

.ds-gen-bar-mention-item.ds-active {
  background: color-mix(in oklch, var(--design-accent), transparent 90%);
}

.ds-gen-bar-mention-thumb {
  width: 2.5rem;
  height: 2.5rem;
  border-radius: var(--design-radius-sm);
  object-fit: cover;
}

.ds-gen-bar-mention-name {
  font-size: 0.875rem;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.ds-gen-bar-mention-meta {
  min-width: 0;
  display: flex;
  flex-direction: column;
}

.ds-gen-bar-mention-source {
  font-size: 0.6875rem;
  line-height: 1.2;
  color: var(--design-muted-fg);
  text-transform: lowercase;
}

.ds-gen-bar-mention-empty {
  padding: 1rem;
  text-align: center;
  font-size: 0.75rem;
  color: var(--design-muted-fg);
}

.ds-gen-bar-mention-browse {
  width: 100%;
  padding: 0.75rem 1rem;
  border: none;
  border-top: 1px solid var(--design-border);
  background: transparent;
  color: var(--design-accent);
  cursor: pointer;
  font-size: 0.75rem;
  text-align: left;
  transition: background 200ms ease;
}

.ds-gen-bar-mention-browse:hover {
  background: color-mix(in oklch, var(--design-accent), transparent 95%);
}

.ds-gen-bar-reference-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 0.375rem;
  padding: 0.5rem 1rem;
  border-top: 1px solid var(--design-border);
}

.ds-gen-bar-reference-chip {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  max-width: 13rem;
  border: 1px solid var(--design-border);
  border-radius: 9999px;
  background: color-mix(in oklch, var(--design-accent), transparent 93%);
  color: var(--design-fg);
  padding: 0.25rem 0.4rem 0.25rem 0.25rem;
  cursor: pointer;
}

.ds-gen-bar-reference-chip-thumb {
  width: 1.1rem;
  height: 1.1rem;
  border-radius: 9999px;
  object-fit: cover;
}

.ds-gen-bar-reference-chip-label {
  font-size: 0.75rem;
  line-height: 1.1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.ds-gen-bar-reference-chip-remove {
  font-size: 0.75rem;
  color: var(--design-muted-fg);
}

/* Ambient model chip */
.ds-gen-bar-ambient {
  padding: 0 1rem 0.75rem;
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.ds-gen-bar-ambient-dot {
  width: 6px;
  height: 6px;
  border-radius: 9999px;
  background: var(--design-accent);
  opacity: 0.7;
}

.ds-gen-bar-ambient-text {
  font-size: 0.75rem;
  color: var(--design-muted-fg);
  flex: 1;
}

/* AC: @draft-generation-mode ac-1 - Draft mode toggle (ambient mode inline) */
.ds-gen-bar-draft-toggle {
  padding: 0.25rem 0.5rem;
  border-radius: var(--design-radius-sm);
  border: 1px solid var(--design-border);
  background: transparent;
  color: var(--design-muted-fg);
  font-size: 0.625rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  cursor: pointer;
  transition:
    border-color 200ms ease,
    background 200ms ease,
    color 200ms ease;
}

.ds-gen-bar-draft-toggle:hover {
  border-color: var(--design-accent);
  color: var(--design-fg);
}

.ds-gen-bar-draft-toggle.ds-active {
  border-color: var(--design-primary);
  background: color-mix(in oklch, var(--design-primary), transparent 85%);
  color: var(--design-fg);
}

/* Expanded controls */
.ds-gen-bar-controls {
  border-top: 1px solid var(--design-border);
  padding: 1rem;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  animation: ds-controls-reveal 300ms ease-out forwards;
}

/* AC-7: Manual mode indicator */
.ds-gen-bar-mode-indicator {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-bottom: 0.5rem;
  margin-bottom: 0.25rem;
  border-bottom: 1px solid var(--design-border);
  font-size: 0.625rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--design-accent);
}

.ds-gen-bar-mode-close {
  width: 1.5rem;
  height: 1.5rem;
  border-radius: var(--design-radius-sm);
  border: none;
  background: transparent;
  color: var(--design-muted-fg);
  cursor: pointer;
  font-size: 1rem;
  display: flex;
  align-items: center;
  justify-content: center;
  transition:
    color 200ms ease,
    background 200ms ease;
}

.ds-gen-bar-mode-close:hover {
  color: var(--design-fg);
  background: color-mix(in oklch, var(--design-accent), transparent 90%);
}

.ds-gen-bar-control-row {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.ds-gen-bar-control-row-full {
  flex-direction: column;
  align-items: stretch;
}

.ds-gen-bar-control-row-full .ds-gen-bar-control-label {
  width: auto;
  margin-bottom: 0.25rem;
}

.ds-gen-bar-control-label {
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--design-muted-fg);
  width: 5.5rem;
  flex-shrink: 0;
}

.ds-gen-bar-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 0.375rem;
}

.ds-gen-bar-chip {
  padding: 0.25rem 0.625rem;
  border-radius: var(--design-radius-sm);
  border: 1px solid var(--design-border);
  background: transparent;
  color: var(--design-muted-fg);
  font-size: 0.75rem;
  cursor: pointer;
  transition:
    border-color 200ms ease,
    background 200ms ease,
    color 200ms ease;
}

.ds-gen-bar-chip:hover {
  border-color: var(--design-accent);
  color: var(--design-fg);
}

.ds-gen-bar-chip.ds-active {
  border-color: var(--design-primary);
  background: color-mix(in oklch, var(--design-primary), transparent 85%);
  color: var(--design-fg);
}

/* AC-10: Aspect ratio chips with visual boxes */
.ds-gen-bar-ratio-chip {
  display: flex;
  align-items: center;
  gap: 0.375rem;
}

.ds-gen-bar-ratio-box {
  opacity: 0.7;
}

.ds-gen-bar-chip.ds-active .ds-gen-bar-ratio-box {
  opacity: 1;
}

/* Manual mode text inputs */
.ds-gen-bar-input {
  flex: 1;
  padding: 0.5rem 0.75rem;
  border: 1px solid var(--design-border);
  border-radius: var(--design-radius-md);
  background: transparent;
  color: var(--design-fg);
  font-size: 0.875rem;
  outline: none;
  transition: border-color 200ms ease;
}

.ds-gen-bar-input:focus {
  border-color: var(--design-accent);
}

.ds-gen-bar-input::placeholder {
  color: var(--design-muted-fg);
}

.ds-gen-bar-input-short {
  max-width: 8rem;
}

/* AC-3: Toggle switch for manual mode */
.ds-gen-bar-toggle {
  padding: 0;
  border: none;
  background: transparent;
  cursor: pointer;
}

.ds-gen-bar-toggle-track {
  display: block;
  width: 2.5rem;
  height: 1.25rem;
  border-radius: 9999px;
  background: var(--design-border);
  position: relative;
  transition: background 200ms ease;
}

.ds-gen-bar-toggle.ds-active .ds-gen-bar-toggle-track {
  background: var(--design-primary);
}

.ds-gen-bar-toggle-thumb {
  position: absolute;
  top: 0.125rem;
  left: 0.125rem;
  width: 1rem;
  height: 1rem;
  border-radius: 9999px;
  background: var(--design-bg);
  transition: transform 200ms ease;
}

.ds-gen-bar-toggle.ds-active .ds-gen-bar-toggle-thumb {
  transform: translateX(1.25rem);
}

/* Reference image drop zone */
.ds-gen-bar-dropzone {
  flex: 1;
  border: 1.5px dashed var(--design-border);
  border-radius: var(--design-radius-md);
  padding: 0.75rem;
  text-align: center;
  font-size: 0.75rem;
  color: var(--design-muted-fg);
  transition:
    border-color 300ms ease,
    background 300ms ease;
  cursor: pointer;
}

.ds-gen-bar-dropzone:hover {
  border-color: var(--design-accent);
  background: color-mix(in oklch, var(--design-accent), transparent 95%);
}

/* Bottom hint + generate */
.ds-gen-bar-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.ds-gen-bar-hint {
  font-size: 0.75rem;
  color: var(--design-muted-fg);
}

/* Progress bar */
.ds-gen-bar-progress {
  position: absolute;
  bottom: 0;
  left: 0;
  height: 2px;
  background: var(--design-primary);
  border-radius: 0 0 var(--design-radius-xl) var(--design-radius-xl);
  animation: ds-gen-progress 3s ease-out forwards;
}

/* Keyframes */
@keyframes ds-gen-breathe {
  0%,
  100% {
    box-shadow:
      0 0 0 0 color-mix(in oklch, var(--design-accent), transparent 90%),
      inset 0 0 20px color-mix(in oklch, var(--design-accent), transparent 95%);
  }
  50% {
    box-shadow:
      0 0 20px 2px color-mix(in oklch, var(--design-accent), transparent 80%),
      inset 0 0 30px color-mix(in oklch, var(--design-accent), transparent 90%);
  }
}

@keyframes ds-gen-progress {
  from {
    width: 0%;
  }
  to {
    width: 100%;
  }
}

@keyframes ds-controls-reveal {
  from {
    opacity: 0;
    transform: translateY(-10px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@media (prefers-reduced-motion: reduce) {
  .ds-gen-bar,
  .ds-gen-bar-progress,
  .ds-gen-bar-controls {
    animation: none !important;
    transition-duration: 0.01ms !important;
  }
}

/* Responsive: Mobile (under 768px) */
@media (max-width: 767px) {
  .ds-gen-bar-section {
    padding: 1rem 1rem 3rem;
  }

  .ds-gen-bar-section.ds-gen-bar-section-floating {
    padding: 0.5rem 0.5rem calc(0.5rem + env(safe-area-inset-bottom));
  }

  .ds-gen-bar-input-row {
    padding: 0.75rem;
    gap: 0.5rem;
  }

  /* Stack controls vertically on mobile */
  .ds-gen-bar-control-row {
    flex-direction: column;
    align-items: stretch;
    gap: 0.5rem;
  }

  .ds-gen-bar-control-label {
    width: auto;
  }

  .ds-gen-bar-chips {
    justify-content: flex-start;
  }

  /* Touch-friendly targets (44px minimum) */
  .ds-gen-bar-chip {
    min-height: 2.75rem;
    padding: 0.5rem 0.75rem;
    font-size: 0.875rem;
  }

  .ds-gen-bar-image-btn,
  .ds-gen-bar-overflow-btn {
    width: 2.75rem;
    height: 2.75rem;
  }

  .ds-gen-bar-submit-btn {
    min-height: 2.75rem;
    min-width: 4rem;
  }

  /* Mention popup full width on mobile */
  .ds-gen-bar-mention-popup {
    max-height: 12rem;
  }

  .ds-gen-bar-mention-item {
    min-height: 2.75rem;
  }

  /* Thumbnails smaller on mobile */
  .ds-gen-bar-thumbnail {
    width: 3rem;
    height: 3rem;
  }

  .ds-gen-bar-thumbnail-remove {
    opacity: 1;
  }
}

