/* AC: @gallery-home ac-3 - Skeleton card for in-progress jobs */
.ds-skeleton {
  border-radius: var(--design-radius-lg);
  background: var(--design-card);
  overflow: hidden;
}

.ds-skeleton-inner {
  position: relative;
  width: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
}

.ds-skeleton-shimmer {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    90deg,
    transparent 0%,
    color-mix(in oklch, var(--design-accent), transparent 90%) 50%,
    transparent 100%
  );
  background-size: 200% 100%;
  animation: ds-skeleton-shimmer 2s ease-in-out infinite;
}

/* AC: @gallery-home ac-3, @generation-progress-ux ac-2 - Progress indicator bar */
.ds-skeleton-progress {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: color-mix(in oklch, var(--design-accent), transparent 85%);
  overflow: hidden;
}

/* AC: @generation-progress-ux ac-2 - Determinate progress bar */
.ds-skeleton-progress-bar {
  height: 100%;
  background: var(--design-accent);
  transition: width 300ms ease-out;
}

/* AC: @generation-progress-ux ac-3 - Indeterminate sweep animation */
.ds-skeleton-progress-sweep {
  position: absolute;
  height: 100%;
  width: 30%;
  background: linear-gradient(90deg, transparent 0%, var(--design-accent) 50%, transparent 100%);
  animation: ds-skeleton-progress-sweep 1.5s ease-in-out infinite;
}

@keyframes ds-skeleton-progress-sweep {
  0% {
    transform: translateX(-100%);
    left: 0;
  }
  100% {
    transform: translateX(100%);
    left: 100%;
  }
}

.ds-skeleton-content {
  position: relative;
  z-index: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.375rem;
  padding: 0.5rem;
}

/* AC: @generation-progress-ux ac-1, ac-2, ac-4 - Status text styling */
.ds-skeleton-status {
  font-size: 0.875rem;
  color: var(--design-accent);
  font-weight: 500;
}

.ds-skeleton-text {
  font-size: 0.75rem;
  color: var(--design-muted-fg);
  text-align: center;
}

.ds-skeleton-percent {
  font-size: 0.875rem;
  color: var(--design-fg);
  font-weight: 500;
}

@keyframes ds-skeleton-shimmer {
  0% {
    background-position: 200% 0;
  }
  100% {
    background-position: -200% 0;
  }
}

/* AC: @gallery-home ac-13, @job-cancellation ac-1 - Cancel button */
.ds-skeleton-cancel {
  position: absolute;
  top: 0.5rem;
  right: 0.5rem;
  z-index: 2;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  background: color-mix(in oklch, var(--design-card), transparent 20%);
  border: 1px solid var(--design-border);
  border-radius: var(--design-radius-md);
  color: var(--design-muted-fg);
  cursor: pointer;
  transition:
    background 200ms ease,
    color 200ms ease,
    border-color 200ms ease;
  backdrop-filter: blur(4px);
}

.ds-skeleton-cancel:hover {
  background: var(--design-destructive);
  border-color: var(--design-destructive);
  color: var(--design-accent-foreground);
}

.ds-skeleton-cancel:focus-visible {
  outline: 2px solid var(--design-ring);
  outline-offset: 2px;
}

@media (prefers-reduced-motion: reduce) {
  .ds-skeleton-shimmer,
  .ds-skeleton-progress-sweep {
    animation: none !important;
  }
}

