/**
 * Design System Component Registry
 *
 * Agent-readable catalog of every component, hook, utility, and type
 * exported by @imgen/design-system. Read this file FIRST to discover
 * the full API before creating or extending components.
 *
 * This file is type-checked but NOT imported at runtime.
 */

// ---------------------------------------------------------------------------
// Registry shape types
// ---------------------------------------------------------------------------

interface ComponentEntry {
  /** Relative path from package root to implementation file */
  path: string;
  /** Component category */
  category: "input" | "display" | "content" | "navigation" | "feedback" | "utility";
  /** Where this component should be used: 'app' (core app), 'landing' (marketing pages only), 'both' (universal) */
  scope: "app" | "landing" | "both";
  /** Whether this component can be used in React Server Components */
  serverSafe: false;
  /** One-sentence description of what this component does */
  description: string;
  /** Props summary — key prop names with their types */
  props: Record<string, string>;
  /** Design tokens this component depends on (full token names) */
  tokens: string[];
  /** Types/components imported from other packages */
  dependencies: { shared?: string[]; ui?: string[] };
  /** One-line JSX usage example (as a string) */
  example: string;
}

interface HookEntry {
  path: string;
  category: "state" | "layout" | "interaction";
  description: string;
  /** Name of the options/params type */
  params: string;
  /** Name of the return type (or inline description) */
  returns: string;
  example: string;
}

interface UtilityEntry {
  path: string;
  serverSafe: boolean;
  description: string;
  example: string;
}

interface Registry {
  components: Record<string, ComponentEntry>;
  hooks: Record<string, HookEntry>;
  utilities: Record<string, UtilityEntry>;
  types: readonly string[];
}

// ---------------------------------------------------------------------------
// Registry
// ---------------------------------------------------------------------------

export const REGISTRY: Registry = {
  components: {
    GenerationBar: {
      path: "./components/generation-bar/generation-bar.tsx",
      category: "input",
      scope: "app",
      serverSafe: false,
      description:
        "Two-mode generation bar: ambient mode (auto-routing, minimal UI) and manual mode (full controls). Supports @-mention system, drag-drop images, preview toggle, validation, and success animation.",
      props: {
        models: "ModelDefinition[]",
        onGenerate: "(params: GenerateParams) => void",
        placeholders: "string[]",
        labels: "GenerationBarLabels (optional)",
        id: 'string (optional, default: "generate")',
        defaultModel: "string (optional) - AC: @user-preferences ac-3",
        defaultAspectRatio: "string (optional) - AC: @user-preferences ac-4",
        defaultQuality: '"standard" | "hd" (optional)',
        sessionImages: "ImageReference[] (optional) - images for @-mention",
        onBrowseGallery: "() => void (optional) - callback to open gallery browser",
        galleryImages: "ImageReference[] (optional) - gallery images for browsing",
      },
      tokens: [
        "--design-card",
        "--design-border",
        "--design-primary",
        "--design-accent",
        "--design-muted-fg",
        "--design-fg",
        "--design-bg",
        "--design-radius-xl",
        "--design-radius-lg",
        "--design-radius-md",
        "--design-radius-sm",
      ],
      dependencies: {
        shared: ["ModelDefinition", "GenerateParams", "ImageReference", "GenerationBarMode"],
        ui: ["Button"],
      },
      example:
        '<GenerationBar models={models} onGenerate={handleGenerate} placeholders={["A copper forge at golden hour"]} sessionImages={sessionImages} onBrowseGallery={openGalleryBrowser} />',
    },

    ImageLightbox: {
      path: "./components/image-lightbox/image-lightbox.tsx",
      category: "display",
      scope: "app",
      serverSafe: false,
      description:
        "Fullscreen image viewer with prev/next navigation, keyboard support (Escape, Arrow keys), focus trap, metadata display, and image deletion.",
      props: {
        image: "GalleryImage | null",
        images: "GalleryImage[]",
        onClose: "() => void",
        onNavigate: "(imageId: string) => void",
        onDelete: "(imageId: string) => void (optional) — delete with two-step confirmation",
        isDeleting: "boolean (optional) — whether deletion is in progress",
      },
      tokens: [
        "--design-bg",
        "--design-fg",
        "--design-card",
        "--design-border",
        "--design-muted-fg",
        "--design-secondary",
        "--design-accent",
        "--design-radius-xl",
        "--design-radius-lg",
        "--design-radius-md",
      ],
      dependencies: { shared: ["GalleryImage"] },
      example:
        "<ImageLightbox image={selectedImage} images={allImages} onClose={() => setSelected(null)} onNavigate={setSelectedById} />",
    },

    GalleryCard: {
      path: "./components/gallery-card/gallery-card.tsx",
      category: "display",
      scope: "app",
      serverSafe: false,
      description:
        "Masonry gallery image card with scroll-reveal animation, hover overlay showing prompt and metadata, keyboard activation, and selection mode support.",
      props: {
        image: "GalleryImage",
