 1→<script lang="ts">
 2→	import { onMount } from 'svelte';
 3→	import favicon from '$lib/assets/favicon.svg';
 4→	import '../app.css';
 5→	import { SidebarProvider, SidebarInset } from '$lib/components/ui/sidebar';
 6→	import Sidebar from '$lib/components/Sidebar.svelte';
 7→	import MobileNav from '$lib/components/MobileNav.svelte';
 8→	import CommandPalette from '$lib/components/CommandPalette.svelte';
 9→	import ReadOnlyBanner from '$lib/components/ReadOnlyBanner.svelte';
10→	import { initConnection } from '$lib/stores/connection.svelte';
11→	import { loadProjects, getSelectedProjectPath, isInitialized } from '$lib/stores/project.svelte';
12→	import { initMode, isStaticMode, isLoading as isModeLoading } from '$lib/stores/mode.svelte';
13→	import { browser } from '$app/environment';
14→
15→	let { children } = $props();
16→
17→	// Track if app is ready (mode detected and projects loaded if in daemon mode)
18→	let appReady = $state(false);
19→
20→	// AC: @web-dashboard ac-28 - Initialize WebSocket connection
21→	// AC: @multi-directory-daemon ac-25 - Load projects list on mount
22→	// AC: @gh-pages-export ac-11 - Mode detection before initialization
23→	onMount(async () => {
24→		// First: detect mode (daemon or static)
25→		await initMode();
26→
27→		// In static mode, skip project loading and WebSocket
28→		// AC: @gh-pages-export ac-11 - Static mode uses embedded JSON
29→		if (isStaticMode()) {
30→			appReady = true;
31→			return;
32→		}
33→
34→		// In daemon mode: load projects and connect WebSocket
35→		await loadProjects();
36→		appReady = true;
37→
38→		// Initialize WebSocket with selected project
39→		const projectPath = getSelectedProjectPath();
40→		initConnection({ projectPath: projectPath ?? undefined });
41→	});
42→
43→	// For SSR, treat as ready since we can't have a selected project anyway
44→	let ready = $derived(browser ? appReady : true);
45→</script>
46→
47→<svelte:head>
48→	<link rel="icon" href={favicon} />
49→</svelte:head>
50→
51→<!-- AC: @web-dashboard ac-23 - Global command palette -->
52→<CommandPalette />
53→
54→<!-- AC: @web-dashboard ac-26, ac-27 -->
55→<SidebarProvider>
56→	<!-- Desktop sidebar (hidden on mobile) -->
57→	<div class="hidden md:block">
58→		<Sidebar />
59→	</div>
60→
61→	<!-- Main content area with responsive inset -->
62→	<SidebarInset>
63→		<!-- AC: @gh-pages-export ac-15 - Show read-only banner in static mode -->
64→		<ReadOnlyBanner />
65→
66→		<main class="flex-1 overflow-auto p-4 pb-20 md:pb-4">
67→			{#if ready}
68→				{@render children()}
69→			{:else}
70→				<!-- AC: @multi-directory-daemon ac-25 - Wait for projects to load -->
71→				<div class="flex items-center justify-center h-32">
72→					<span class="text-muted-foreground">Loading...</span>
73→				</div>
74→			{/if}
75→		</main>
76→	</SidebarInset>
77→
78→	<!-- Mobile bottom navigation (hidden on desktop) -->
79→	<MobileNav />
80→</SidebarProvider>
