--design-primary         /* Active/committed: buttons, selected chips, CTAs, progress */
--design-primary-fg      /* Text on primary backgrounds */
--design-secondary       /* Secondary action color */
--design-secondary-fg    /* Text on secondary */
--design-muted           /* Disabled/deemphasized backgrounds */
--design-muted-fg        /* Disabled/deemphasized text */
--design-accent          /* Decorative + hover: eyebrows, markers, glow, shimmer, hover states */
--design-accent-fg       /* Text on accent backgrounds */
--design-destructive     /* Error/delete actions */
--design-border          /* Border color */
--design-input           /* Input field backgrounds */
