├── lib/
│   └── style-storage.ts        # Storage key helpers
├── hooks/
│   ├── use-style-switcher.ts   # Theme/style switching
│   ├── use-scroll-reveal.ts    # Scroll animations
│   └── ...
└── components/
    ├── generation-bar/
    │   ├── generation-bar.tsx
    │   └── generation-bar.css
    ├── image-lightbox/
    ├── gallery-card/
    ├── skeleton-card/
    └── ...
```

---

### 7. INTEGRATION WITH TAILWIND

The gallery app's globals.css maps design tokens to Tailwind theme:

```css
@theme inline {
  --color-background: var(--design-bg);
  --color-foreground: var(--design-fg);
  --color-card: var(--design-card);
  --color-primary: var(--design-primary);
  --color-accent: var(--design-accent);
  --color-destructive: var(--design-destructive);
