  --font-heading: var(--font-design-secondary);
  --font-mono: var(--font-design-mono, ui-monospace, monospace);
}
```

---

### 8. RUNTIME THEME SWITCHING

**Storage pattern** (from `lib/style-storage.ts`):
```typescript
export function getStyleStorageKey(designId: number | string): string {
  return `imgen-d${designId}-style`;
